def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.employees = pyo.Set(initialize=d["employees"])
    model.projects = pyo.Set(initialize=d["projects"])
    model.pairs = pyo.Set(
        initialize=[(i, j) for i in d["employees"] for j in d["projects"]],
        dimen=2,
    )

    # Decision variable: 1 if employee i assigned to project j
    model.assign = pyo.Var(model.pairs, within=pyo.Binary)

    # Objective: minimize total assignment cost
    def obj_rule(m):
        return sum(d["cost"][i][j] * m.assign[i, j] for (i, j) in m.pairs)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # Each employee must contribute exactly their required total hours
    def emp_hours_rule(m, i):
        return sum(
            d["limit"][i][j] * m.assign[i, j] for j in m.projects
        ) == d["emp_hours"][i]

    model.emp_hours_con = pyo.Constraint(model.employees, rule=emp_hours_rule)

    # Each project must receive exactly its required total hours
    def proj_hours_rule(m, j):
        return sum(
            d["limit"][i][j] * m.assign[i, j] for i in m.employees
        ) == d["proj_hours"][j]

    model.proj_hours_con = pyo.Constraint(model.projects, rule=proj_hours_rule)

    return model
